export function createImageTools(React){const Icon=createStudioIcon(React),{AnglePanel}=createStudioInputs(React);const{createElement:h,useState:S,useRef:R}=React;
 const presets={
 character:['Character sheet · 3 phần liền mạch',"Create a photorealistic three-panel character reference sheet based strictly on the uploaded source image. The source image is the single source of truth for identity, age, facial structure, hairstyle, body proportions, skin tone, clothing design, fabric, colors and accessories. Do not redesign or reinterpret.\n\nLAYOUT: ONE horizontal landscape image, exactly 16:9. Read left to right as three vertical panel areas of exactly equal width and equal height. Each area occupies precisely one third of the total image width. All areas form one continuous seamless composition: no visible dividers, borders, frames, gutters, gaps, spacing or background changes.\n\nPANEL 1 — FULL-BODY FRONT VIEW, HEAD OMITTED: Stand straight, neutral pose, arms naturally at sides, facing the camera. Show the complete outfit from neckline to footwear. FIRST establish precisely the same full-body scale and framing as Panel 2; THEN omit only the head information above the neckline, leaving ordinary empty background where the head would have been. This is a clean technical costume presentation. No injury, blood, wound, severed neck, anatomical damage or surreal effect. Never enlarge, zoom, reframe, shift or re-crop the body to compensate for the absent head.\n\nPANEL 2 — FULL-BODY REAR VIEW: The identical character directly from behind, standing in the same neutral pose, arms at sides. Show the exact rear hairstyle, back silhouette, garment construction, seams, lower-body garment and footwear from the source. Keep the whole figure and shoes in frame.\n\nSCALE LOCK FOR PANELS 1 AND 2: Like consecutive tripod photographs with identical focal length, camera height, distance, subject scale and lighting. Match on-screen shoulder width, torso length, leg length, shoe size, shoulder-to-floor distance and side margins. Both bodies share exactly one horizontal shoulder line and one ground baseline; both occupy the same percentage of panel height. No zoom, crop, vertical shift or body-size difference. Near-orthographic technical perspective with minimal distortion.\n\nPANEL 3 — FACE AND UPPER-BODY CLOSE-UP: Crop from upper chest upward. Turn the head subtly to the subject's RIGHT so the subject's LEFT cheek is more exposed and the nose points slightly to the subject's right. Keep the face mostly toward camera, both eyes clearly visible and eye contact directed at the camera. Do not make a symmetrical frontal portrait. Serious neutral expression. Keep the entire head, hairstyle, hair outline and chin in frame, with a little space above the hair. Preserve exact source identity, age, facial structure, skin texture, wrinkles and natural asymmetry.\n\nCONSISTENCY: Identical age, skin tone, hairstyle, body proportions, wardrobe, garment cuts, fabrics, colors and accessories across all three areas. Preserve source design exactly. Technical visual reference and costume documentation, not creative reinterpretation. Only Panel 3 displays a visible face, so downstream generation has one unambiguous identity anchor.\n\nBACKGROUND: Neutral mid-grey #808080, continuous across the whole sheet with identical color, brightness and lighting. No interruptions or panel separation.\n\nLIGHTING AND RENDER: Clean soft even studio lighting, large diffused key and gentle fill, soft natural shadows, neutral white balance, realistic skin and material texture. Full-frame 85mm editorial photography, deep controlled depth of field, whole figures sharply focused, crisp detail without sharpening halos. Clean professional model-sheet finish.\n\nNEGATIVE: No text, labels, typography, measurements, additional logos, props, furniture, environmental objects, graphic decorations, divider lines, borders, frames, gutters, panel gaps or visible seams between areas. No unequal panel widths. No colored light, rim light, harsh spotlight or theatrical lighting. Do not remove or alter authentic clothing details present in the source."],
 product:['Product sheet · Front / 3⁄4', 'Create ONE horizontal 16:9 photorealistic product reference image from the uploaded source. Present the exact same product twice: a straight front view and a three-quarter perspective view, equally prominent. Preserve exact geometry, proportions, brand marks, label typography, materials, finish, colors and all visible authentic details. Do not redesign, invent specifications, or transfer a different product. Use one continuous neutral grey studio background, consistent product scale, lens, soft even lighting and restrained natural contact shadows. Keep the full product visible in both views, with crisp material detail and no decorative headings, captions, borders or additional logos. This is a reusable visual asset for consistent cinematic scenes, not an advertising layout.'],
 props:['Props sheet','Create ONE horizontal 16:9 prop reference sheet from the supplied object. Show front, side, back and three-quarter views with a small material/detail section. Preserve geometry, proportions, original colors and texture. Same object in all views, neutral background, consistent scale, clean separators, no text or watermarks.'],
 expression:['Expression sheet','Create ONE horizontal 16:9 expression reference sheet with six well-separated head portraits of the same character: neutral, gentle smile, laugh, surprised, serious and sad. Preserve exact identity, face geometry, age, hairstyle, outfit and lighting. Consistent head size and camera distance, neutral background, no text or watermarks.'],
 environment:['Environment sheet','Create ONE horizontal 16:9 environment reference sheet of the supplied scene: wide establishing view, reverse view, left and right views, plus two architectural/material details. Keep the same scene geometry, objects, materials, palette and time of day. Clear panel spacing and coherent perspective, no text or watermark.'],
 angles:['Góc chụp','Change only the camera to the selected angle. Preserve identity, object geometry, clothing, material, lighting and background. Reconstruct unseen surfaces plausibly without inventing logos or text.'],
 outfit:['Thay quần áo','Change ONLY the clothing of the person in the first/source image using the clothing in the second/reference image. Preserve the source face, identity, pose, body proportions, hair, scene and lighting. Match fabric texture, fit, folds and natural shadows. Do not copy the reference face.'],
 replace:['Thay sản phẩm','Replace ONLY the requested product/object in the first/source image using the product in the second/reference image. Preserve exact reference geometry, label, logo, material and color. Match scene perspective, scale, occlusion, contact shadows and reflections. Preserve the rest of the original scene.'],
 background:['Thay background','Replace ONLY the background using the second/reference image or the scene described below. Preserve the first/source subject, facial identity, clothing, pose and silhouette. Match lighting and contact shadows naturally; maintain clean hair and object edges.'],
 detail:['Sửa chi tiết','Edit only the region and detail described below. Preserve all other regions, identity, geometry, colors and materials. Use the region drawing tool to specify the exact area when needed.'],
 enhance:['Enhance','Enhance the source photo conservatively: reduce compression artifacts and mild blur, restore natural edge definition and material texture, reduce noise while preserving fine grain. Keep exact identity, composition, colors, text, logo and geometry. No invented details, plastic skin, halos or over-sharpening.']};
 const angles=[['front','Chính diện','front view, camera at eye level'],['threequarter','Góc 3/4','three-quarter view, 45-degree horizontal angle'],['left','Nghiêng trái','left profile view, 90-degree horizontal angle'],['right','Nghiêng phải','right profile view, 90-degree horizontal angle'],['back','Mặt sau','rear view'],['high','Từ trên xuống','high-angle view, camera tilted down 35 degrees'],['low','Từ dưới lên','low-angle view, camera tilted up 25 degrees'],['top','Top-down','overhead top-down view, camera perpendicular to the subject']];
 function ImageTools({prompt,onPrompt,refs,composer,onComposer,onRatio,onError,onUpscale,busy}){const[chosen,CH]=S(composer.studioPreset||''),[angle,AN]=S('threequarter'),[thinking,TH]=S(false),[before,BF]=S(null);const inserted=R('');const sheetKeys=['character','product','props','expression','environment'];
 const labels={character:'Nhân vật',product:'Sản phẩm',props:'Đạo cụ',expression:'Biểu cảm',environment:'Bối cảnh',angles:'Đổi góc chụp',outfit:'Thay trang phục',replace:'Thay sản phẩm',background:'Thay phông nền',detail:'Chỉnh sửa chi tiết',enhance:'Cải thiện độ nét',remove:'Xóa vật thể',relight:'Đổi ánh sáng',color:'Đổi màu',expand:'Mở rộng khung'};
 const editKeys=['outfit','replace','background','angles','detail','remove','relight','color','expand','enhance'];
 const selected=(Array.isArray(composer.editTools)?composer.editTools:editKeys.includes(chosen)?[chosen]:[]).filter(k=>editKeys.includes(k)).slice(-1);
 const START='[MUSE EDIT PLAN]',END='[/MUSE EDIT PLAN]';
 function instructions(keys){const lines={enhance:'Khôi phục độ rõ và chi tiết tự nhiên của ảnh. Giảm nhiễu, sửa nhòe nhẹ, giữ nguyên khuôn mặt, kết cấu, màu sắc và bố cục; không thêm chi tiết giả.',outfit:'Thay trang phục bằng bộ đồ theo ảnh tham chiếu nếu có; nếu không, dùng trang phục tối giản, thanh lịch và phù hợp với chủ thể. Giữ nguyên khuôn mặt, tóc, vóc dáng, tư thế và bối cảnh.',replace:'Thay sản phẩm trong ảnh gốc bằng sản phẩm tham chiếu nếu có. Giữ đúng hình dáng, nhãn, vật liệu và màu sắc của sản phẩm; khớp phối cảnh, ánh sáng và bóng đổ.',background:'Thay phông nền theo ảnh tham chiếu nếu có; nếu không, dùng nền studio xám trung tính với ánh sáng mềm. Giữ nguyên chủ thể, chất liệu, chi tiết và rìa tóc tự nhiên.',angles:'Đổi sang góc chụp ba phần tư tự nhiên. Giữ đúng nhận diện, hình dáng, vật liệu và bối cảnh; dựng lại phối cảnh hợp lý thay vì xoay ảnh phẳng.',detail:'Chỉnh các chi tiết chưa tự nhiên, làm sạch lỗi nhỏ và vùng đánh dấu nếu có. Giữ nguyên cấu trúc, nhận diện, bố cục và các vùng còn lại.',remove:'Xóa các vật thể thừa gây mất tập trung ở hậu cảnh hoặc trong vùng đã đánh dấu. Giữ chủ thể chính và khôi phục nền liền mạch, tự nhiên.',relight:'Điều chỉnh sang ánh sáng studio mềm, cân bằng vùng sáng tối. Giữ màu sắc, chất liệu và hình dáng; bóng đổ và phản chiếu phải tự nhiên.',color:'Cân chỉnh màu sắc trung tính, hài hòa và tự nhiên. Chỉ đổi màu đối tượng khi có yêu cầu cụ thể; giữ nguyên chất liệu, hình dáng, nhãn và chi tiết.',expand:'Mở rộng ảnh tự nhiên theo tỷ lệ khung hình đã chọn. Giữ toàn bộ chủ thể và nội dung ảnh gốc, không kéo giãn; bổ sung nền liền mạch.'};return keys.map(k=>lines[k]).join('\n')+'\nXuất một ảnh hoàn chỉnh. Không thêm chữ, logo, watermark hoặc thay đổi các phần không được yêu cầu.';}

 function choose(key){BF(prompt);const sheet=sheetKeys.includes(key);if(sheet){CH(key);onRatio('16:9');onComposer({...composer,mode:refs.length?'edit':'create',editTools:[],annotation:null,ratioMode:'manual',studioPreset:key});onPrompt(presets[key][1]+'\n\n');return}
 const next=[key];CH(next.at(-1)||'');onComposer({...composer,mode:'edit',editTools:next,studioPreset:next.at(-1)||''});
 const start=prompt.indexOf(START),end=prompt.indexOf(END);let extra=start>=0&&end>=start?(prompt.slice(0,start)+prompt.slice(end+END.length)).trim():prompt.trim();if(inserted.current&&extra.startsWith(inserted.current))extra=extra.slice(inserted.current.length).trim();if(Object.values(presets).some(p=>extra.startsWith(p[1])))extra='';const ready=instructions(next);inserted.current=ready;onPrompt(ready+(extra?'\n\n'+extra:''));}

 async function improve(){TH(true);onError('');BF(prompt);try{const response=await fetch('/api/prompt-assistant/improve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:prompt.trim()?'refine':'generate',kind:'image',prompt,references:refs.filter(r=>!r.missing).map(r=>({tag:r.tag,role:composer.roles?.[r.tag]||'reference'}))})});const data=await response.json();if(!response.ok)throw Error(data.error);onPrompt(data.prompt)}catch(e){onError(e.message)}finally{TH(false)}}
 function group(title,keys){return h('section',{className:'preset-group'},h('h3',null,title),h('div',{className:'image-preset-grid'},...keys.map(key=>h('button',{key,type:'button',className:(sheetKeys.includes(key)?chosen===key:selected.includes(key))?'active':'','aria-pressed':sheetKeys.includes(key)?chosen===key:selected.includes(key),disabled:busy||thinking,onClick:()=>choose(key)},h(Icon,{name:({outfit:'wardrobe',replace:'product',character:'person',expression:'person',environment:'background',props:'product',remove:'detail',relight:'enhance',color:'concept',expand:'view'})[key]||key}),h('span',null,labels[key]),null))))}
 return h('div',{className:'image-presets'},h('header',null,h('span',{className:'native-eyebrow'},'CREATIVE TOOLS'),h('h2',null,'Công cụ chỉnh ảnh'),null),h('p',{className:'preset-help multi-edit-intro'},'Bấm công cụ để điền sẵn yêu cầu. Thêm ảnh rồi bấm Tạo.'),group('Phần cần thay đổi',editKeys),null,null,selected.some(k=>['outfit','replace','background'].includes(k))&&h('p',{className:'preset-help'},'Ảnh 1 là ảnh gốc. Thêm ảnh cho từng phần và chọn vai trò bên dưới ảnh: Trang phục, Vật thể hoặc Bối cảnh. Có thể dùng @ trong mô tả để chỉ rõ ảnh.'))
 }
 return {ImageTools,presets};
}
